#include <vector>
using namespace std;
class Solution {
public:
    vector<int> addTwoNumbers(vector<int>& l1, vector<int>& l2) {
        vector<int> res;
        int carry = 0, i = 0, j = 0;
        while (i < (int)l1.size() || j < (int)l2.size() || carry) {
            int v1 = i < (int)l1.size() ? l1[i++] : 0;
            int v2 = j < (int)l2.size() ? l2[j++] : 0;
            int total = v1 + v2 + carry;
            res.push_back(total % 10);
            carry = total / 10;
        }
        return res;
    }
};
